	}
	d.termMu.Unlock()

	var tmuxSession string
	for _, rPty := range ptys {
		_ = rPty.ptyFile.Close()
		if rPty.cmd.Process != nil {
			_ = rPty.cmd.Process.Kill()
		}
		if req.CloseSession && rPty.usesTmux && tmuxSession == "" {
			tmuxSession = rPty.sessionName
		}
