    return { ok: true, server_url: appRuntime.localServerURL };
  });
  ipcMain.handle("app:set-zoom", (event, zoomPercent) => {
    const zoom = Number(zoomPercent);
    if (!Number.isFinite(zoom) || zoom < 50 || zoom > 200) {
      return { ok: false, error: "invalid zoom" };
